/**
 * @summary College-aware degree requirements (University Core, college/school, and major) with official SCU source URLs and completion status
 */
export const GetDegreeRequirementsQueryParams = zod.object({
  scenarioMajors: zod.coerce.string().optional(),
  scenarioMinors: zod.coerce.string().optional(),
  professionalGoals: zod.coerce
    .string()
    .optional()
    .describe(
      "JSON-encoded plan-scoped student planning goals. These are not official SCU graduation requirements.",
    ),
  plannedCourses: zod.coerce
    .string()
    .optional()
    .describe(
      'Comma-separated course codes the student has PLANNED in the active Degree Plan or Tentative Degree Plan. A planned major course that carries a Core designation marks that Core requirement \"planned\" (never \"completed\"), so the student is not pushed toward adding a duplicate course. Plan-scoped: a tentative scenario never affects the Degree Plan\'s requirement view.',
    ),
});

export const GetDegreeRequirementsResponse = zod.object({
  college: zod
    .string()
    .describe("The student's college as stored in their profile."),
  collegeCode: zod.enum(["CAS", "LSB", "SOE"]),
  major: zod.string().nullable(),
  universityRules: zod.object({
    rules: zod.array(zod.string()),
    sourceUrl: zod.string(),
    sourceLabel: zod.string(),
  }),
  groups: zod.array(
    zod.object({
      id: zod.string(),
      title: zod.string(),
      kind: zod.enum(["university_core", "college", "major"]),
      sourceUrl: zod
        .string()
        .describe(
          "Official SCU source URL this group's requirements were taken from.",
        ),
      sourceLabel: zod.string(),
      academicYear: zod.string(),
      lastVerified: zod
        .string()
        .describe(
          "Date the requirements were last verified against the official SCU source (YYYY-MM-DD).",
        ),
      notes: zod.array(zod.string()),
      items: zod.array(
        zod.object({
          id: zod.string(),
          label: zod.string(),
          description: zod.string(),
          courses: zod
            .array(zod.string())
            .describe(
              'Concrete SCU course codes that satisfy this item (any one). Empty when SCU says \"choose from an approved list\".',
            ),
          phase: zod
            .string()
            .nullish()
            .describe(
              "Core Curriculum phase (Foundations \/ Explorations \/ Integrations) when applicable.",
            ),
          autoTracked: zod
            .boolean()
            .describe(
              "True when completion is computed automatically from the profile's completed courses.",
            ),
          needsVerification: zod
            .boolean()
            .describe(
              'True when SCU defines this as \"choose from an approved list\" — the student tracks it manually rather than the app inventing a course list.',
            ),
          satisfiedBy: zod
            .array(zod.string())
            .describe("Completed course codes that satisfy this item."),
          plannedBy: zod
            .array(zod.string())
            .optional()
            .describe(
              'Planned-but-not-yet-completed course codes that would satisfy this item. Present so the UI can show \"Planned in Schedule\" — a planned course is never reported as completed.',
            ),
          crossSatisfiedBy: zod
            .array(zod.string())
            .optional()
            .describe(
              "Courses matched to this requirement through the catalog's derived Core-area tagging rather than an explicit SCU course list. SCU's bulletin scrape did not capture per-course Core designations, so these matches always set needsVerification and the student must confirm them.",
            ),
          status: zod
            .enum(["completed", "planned", "open"])
            .optional()
            .describe(
              "completed = satisfied by a course with completion provenance; planned = a planned course would satisfy it; open = neither.",
            ),
          complete: zod.boolean(),
        }),
      ),
      autoTrackedCount: zod.number(),
      autoCompletedCount: zod.number(),
      manualCount: zod.number(),
    }),
  ),
});

